// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address fuzzedBaseToken) public {

        address nft = address(0x1234);
        uint128 virtualBaseTokenReserves = 1;
        uint128 virtualNftReserves = 1;
        uint56 changeFee = 0;
        uint16 feeRate = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        bool ok;
        try c.initialize(
            fuzzedBaseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.baseToken() == fuzzedBaseToken);
        } else {
            assertTrue(c.baseToken() == address(0));
        }
    }
}
